// NOTIF PRO v2 (versi console) — tempel di Console browser pada halaman panel.
// Panel hilang kalau halaman di-refresh; tempel ulang untuk memunculkannya lagi.

(function () {
  'use strict';

  if (window.__notifpro) { try { window.__notifpro.hide(); } catch (e) {} }

  // ===================== KONFIGURASI KOLOM =====================
  // Cocokkan dengan judul kolom di tabel (huruf besar/kecil tidak masalah).
  const CFG = {
    storageKey: 'notifpro_v2',
    waitAfterSearchMs: 2500,     // jeda setelah klik "Cari" sebelum tabel dibaca
    searchButton: 'Cari',
    tabs: { withdrawal: 'Withdrawal Pending', deposit: 'Deposit Pending' },
    cols: {
      user:    [/nama\s*pengguna/i, /user\s*name|username/i, /creator/i],
      nominal: [/^jumlah/i],
      tujuan:  [/payment\s*to/i],
      from:    [/payment\s*from/i],
      status:  [/^status$/i],
    },
    ttsUrl: 'https://translate.google.com/translate_tts?ie=UTF-8&client=tw-ob&tl=id&q=',
  };
  // =============================================================

  const ID = 'notifpro';
  const BANKS = /\b(DANA|OVO|GO-?PAY|LINKAJA|SHOPEEPAY|BCA|BNI|BRI|MANDIRI|CIMB(?: NIAGA)?|PERMATA|DANAMON|BSI|BTN|MAYBANK|PANIN|OCBC(?: NISP)?|SEABANK|JAGO|NEO(?: COMMERCE)?|BJB|BTPN|JENIUS|MEGA|SINARMAS|MUAMALAT|ALLO)\b/i;

  const DEFAULTS = {
    modeSel: 'auto',   // auto = ikut alamat halaman; atau 'deposit' / 'withdrawal'
    refreshSec: 15, maxItems: 1, repeat: true,
    minNominal: 0, maxNominal: 0,
    tplDeposit: '{nama} melakukan deposit dengan nominal {nominal} rupiah',
    tplWithdraw: '{nama} melakukan penarikan dengan nominal {nominal} rupiah',
    sfxOn: true, sfxVolume: 1,
    bankFilter: '', skipWords: 'qris, nxpay',
    engine: 'online', voiceName: '',
    rate: 1, volume: 1, muted: false,
  };
  let S = Object.assign({}, DEFAULTS);
  try { Object.assign(S, JSON.parse(localStorage.getItem(CFG.storageKey) || '{}')); } catch (e) {}
  const save = () => { try { localStorage.setItem(CFG.storageKey, JSON.stringify(S)); } catch (e) {} };

  let running = false, scanTimer = null, clockTimer = null;
  const lastRead = new Map(); // id transaksi -> waktu terakhir dibacakan
  let lastSig = '';

  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const norm = (s) => (s || '').replace(/\s+/g, ' ').trim();
  const on = (el, ev, fn) => el.addEventListener(ev, fn);
  // Mode ditentukan otomatis dari alamat halaman (address bar):
  //   ...deposit...  -> deposit,  ...withdraw...  -> withdrawal
  // Cadangan: judul kolom tabel ("Jumlah Penarikan" / "Jumlah Deposit").
  let headerMode = '';
  function modeFromUrl() {
    const p = location.pathname + location.search + location.hash;
    if (/withdraw/i.test(p)) return 'withdrawal';
    if (/deposit/i.test(p)) return 'deposit';
    return '';
  }
  function curMode() {
    if (S.modeSel === 'deposit' || S.modeSel === 'withdrawal') return S.modeSel;
    return modeFromUrl() || headerMode || 'withdrawal';
  }
  const modeLabel = () => (curMode() === 'withdrawal' ? 'Withdrawal' : 'Deposit');

  // ---------- Terbilang (angka -> kata Indonesia) ----------
  function terbilang(n) {
    const s = ['', 'satu', 'dua', 'tiga', 'empat', 'lima', 'enam', 'tujuh', 'delapan', 'sembilan', 'sepuluh', 'sebelas'];
    n = Math.floor(n);
    if (n < 12) return s[n];
    if (n < 20) return terbilang(n - 10) + ' belas';
    if (n < 100) return (terbilang(Math.floor(n / 10)) + ' puluh ' + terbilang(n % 10)).trim();
    if (n < 200) return ('seratus ' + terbilang(n - 100)).trim();
    if (n < 1e3) return (terbilang(Math.floor(n / 100)) + ' ratus ' + terbilang(n % 100)).trim();
    if (n < 2e3) return ('seribu ' + terbilang(n - 1e3)).trim();
    if (n < 1e6) return (terbilang(Math.floor(n / 1e3)) + ' ribu ' + terbilang(n % 1e3)).trim();
    if (n < 1e9) return (terbilang(Math.floor(n / 1e6)) + ' juta ' + terbilang(n % 1e6)).trim();
    if (n < 1e12) return (terbilang(Math.floor(n / 1e9)) + ' miliar ' + terbilang(n % 1e9)).trim();
    return String(n);
  }
  const say = (n) => (Math.floor(n) === 0 ? 'nol' : terbilang(n));

  // ---------- Nada + suara ----------
  // Nada tertanam di script (base64 mp3): deposit = woow, withdraw = faah
  // Deposit dan withdraw memakai nada yang sama ("sound pertama")
  const SFX_PRIMARY = '';
  const SFX = { deposit: SFX_PRIMARY, withdrawal: SFX_PRIMARY };
  const num = (v, d) => { const n = Number(v); return isNaN(n) ? d : n; };

  let audioCtx = null;
  let playing = [];        // sumber audio Web Audio yang sedang/akan diputar
  let playToken = 0;       // naik setiap suara dibatalkan
  let stopHtml = null;     // penghenti suara online versi <audio>
  let chain = Promise.resolve();
  const sfxBuffers = {};

  function unlockAudio() {
    try {
      audioCtx = audioCtx || new (window.AudioContext || window.webkitAudioContext)();
      if (audioCtx.state === 'suspended') audioCtx.resume();
    } catch (e) {}
  }

  function stopSpeech() {
    playToken++;
    playing.forEach((s) => { try { s.stop(); } catch (e) {} });
    playing = [];
    if (stopHtml) { stopHtml(); stopHtml = null; }
    if ('speechSynthesis' in window) speechSynthesis.cancel();
  }

  // menunggu ms milidetik; berhenti lebih awal kalau suara dibatalkan
  function waitMs(ms, token) {
    return new Promise((resolve) => {
      const t0 = Date.now();
      const iv = setInterval(() => {
        if (token !== playToken || Date.now() - t0 >= ms) { clearInterval(iv); resolve(); }
      }, 80);
    });
  }

  function b64ToBuf(b64) {
    const bin = atob(b64);
    const u8 = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
    return u8.buffer;
  }

  async function playSfx(kind, token) {
    if (!S.sfxOn || !SFX[kind]) return;
    try {
      unlockAudio();
      if (!sfxBuffers[kind]) sfxBuffers[kind] = await audioCtx.decodeAudioData(b64ToBuf(SFX[kind]));
      if (token !== playToken) return;
      const buf = sfxBuffers[kind];
      const src = audioCtx.createBufferSource();
      const gain = audioCtx.createGain();
      src.buffer = buf;
      gain.gain.value = num(S.sfxVolume, 1);
      src.connect(gain);
      gain.connect(audioCtx.destination);
      src.start();
      playing.push(src);
      await waitMs(buf.duration * 1000 + 150, token);
    } catch (e) { /* nada dilewati kalau gagal */ }
  }

  // -- suara bawaan browser --
  function speakNative(text) {
    return new Promise((resolve) => {
      if (!('speechSynthesis' in window)) return resolve();
      const u = new SpeechSynthesisUtterance(text);
      u.lang = 'id-ID';
      u.rate = num(S.rate, 1) || 1;
      u.volume = num(S.volume, 1);
      const voices = speechSynthesis.getVoices();
      const v = (S.voiceName && voices.find((x) => x.name === S.voiceName)) || voices.find((x) => /^id/i.test(x.lang));
      if (v) u.voice = v;
      const done = () => resolve();
      u.addEventListener('end', done);
      u.addEventListener('error', done);
      setTimeout(done, 30000);
      speechSynthesis.speak(u);
    });
  }

  // -- suara online (Google Translate TTS) --
  function gmGet(url) {
    return new Promise((resolve, reject) => {
      const req = typeof GM_xmlhttpRequest === 'function' ? GM_xmlhttpRequest
        : (typeof GM !== 'undefined' && GM.xmlHttpRequest ? GM.xmlHttpRequest : null);
      if (!req) return reject(new Error('GM_xmlhttpRequest tidak tersedia'));
      req({
        method: 'GET', url, responseType: 'arraybuffer', timeout: 8000,
        onload: (r) => (r.status === 200 && r.response && r.response.byteLength ? resolve(r.response) : reject(new Error('HTTP ' + r.status))),
        onerror: () => reject(new Error('gagal')),
        ontimeout: () => reject(new Error('timeout')),
      });
    });
  }
  const hasGM = () => typeof GM_xmlhttpRequest === 'function' || (typeof GM !== 'undefined' && !!GM.xmlHttpRequest);

  function chunkText(text, max) {
    const out = [];
    let cur = '';
    text.split(/\.\s+/).forEach((sent) => {
      sent = sent.trim().replace(/\.$/, '');
      if (!sent) return;
      sent += '.';
      if ((cur + ' ' + sent).trim().length <= max) cur = (cur + ' ' + sent).trim();
      else { if (cur) out.push(cur); cur = sent; }
    });
    if (cur) out.push(cur);
    const res = [];
    out.forEach((c) => {
      while (c.length > max) {
        let i = c.lastIndexOf(' ', max);
        if (i <= 0) i = max;
        res.push(c.slice(0, i));
        c = c.slice(i).trim();
      }
      if (c) res.push(c);
    });
    return res;
  }

  // dipakai kalau tidak ada Tampermonkey (versi console): putar lewat elemen <audio>
  async function playOnlineAudio(text, token) {
    for (const c of chunkText(text, 180)) {
      if (token !== playToken) return;
      await new Promise((resolve, reject) => {
        const a = new Audio(CFG.ttsUrl + encodeURIComponent(c));
        a.volume = Math.min(1, Math.max(0, num(S.volume, 1)));
        a.playbackRate = num(S.rate, 1) || 1;
        stopHtml = () => { try { a.pause(); } catch (e) {} resolve(); };
        a.addEventListener('ended', resolve);
        a.addEventListener('error', () => reject(new Error('audio')));
        a.play().catch(reject);
      });
    }
  }

  async function speakOnline(text, token) {
    try {
      if (!hasGM()) { await playOnlineAudio(text, token); return; }
      unlockAudio();
      const buffers = [];
      for (const c of chunkText(text, 180)) {
        const data = await gmGet(CFG.ttsUrl + encodeURIComponent(c));
        buffers.push(await audioCtx.decodeAudioData(data));
        if (token !== playToken) return;
      }
      let t = audioCtx.currentTime + 0.05;
      const rate = num(S.rate, 1) || 1;
      const vol = num(S.volume, 1);
      buffers.forEach((b) => {
        const src = audioCtx.createBufferSource();
        const gain = audioCtx.createGain();
        src.buffer = b;
        src.playbackRate.value = rate;
        gain.gain.value = vol;
        src.connect(gain);
        gain.connect(audioCtx.destination);
        src.start(t);
        t += b.duration / rate;
        playing.push(src);
      });
      await waitMs((t - audioCtx.currentTime) * 1000 + 150, token);
    } catch (e) {
      if (token === playToken) {
        setStatus('Suara online gagal — pakai suara bawaan');
        await speakNative(text);
      }
    }
  }

  const speak = (text, token) => (S.engine === 'online' ? speakOnline(text, token) : speakNative(text));

  // antrean: nada -> suara, satu per satu, tidak bertumpuk
  function enqueue(job) {
    const token = playToken;
    chain = chain.then(() => (token === playToken ? job(token) : null)).catch(() => {});
  }
  function announceItem(it) {
    if (S.muted) return;
    enqueue(async (token) => {
      await playSfx(curMode(), token);
      if (token !== playToken) return;
      await speak(buildText(it), token);
    });
  }
  function sayPlain(text) {
    if (S.muted) return;
    enqueue((token) => speak(text, token));
  }

  // kalimat dari template: {nama} {nominal} {bank} {atasnama} {rekening}
  function buildText(it) {
    const tpl = curMode() === 'deposit' ? S.tplDeposit : S.tplWithdraw;
    const map = {
      nama: it.user || 'pengguna',
      nominal: say(it.amount),
      bank: it.bank || '',
      atasnama: it.holder || '',
      rekening: (it.number || '').split('').join(' '),
    };
    return String(tpl || '')
      .replace(/\{(\w+)\}/g, (m, k) => (k in map ? map[k] : m))
      .replace(/\s+/g, ' ')
      .replace(/\s+([,.])/g, '$1')
      .trim();
  }

  // ---------- Membaca tabel ----------
  function findCol(headers, list) {
    for (const re of list) {
      const i = headers.findIndex((h) => re.test(h));
      if (i >= 0) return i;
    }
    return -1;
  }

  function parseTujuan(raw) {
    const flat = norm(raw);
    const nm = flat.match(/\d[\d -]{5,}\d/);
    const number = nm ? nm[0].replace(/\D/g, '') : '';
    let rest = nm ? flat.replace(nm[0], ' ') : flat;
    let bank = '';
    const bm = rest.match(BANKS);
    if (bm) {
      bank = bm[0];
      rest = rest.replace(bm[0], ' ');
    } else {
      const ls = raw.split('\n').map((l) => l.trim()).filter((l) => l && l.replace(/\D/g, '') !== number);
      if (ls.length >= 2) { rest = ls[0]; bank = ls[1]; }
    }
    return { number, bank, holder: norm(rest) };
  }

  // Untuk kolom berisi dropdown (mis. Payment From): ambil pilihan yang aktif saja,
  // bukan semua opsi di dalam dropdown.
  function cellText(td) {
    const sel = td.querySelector('select');
    if (sel && sel.selectedIndex >= 0 && sel.options[sel.selectedIndex]) {
      return norm(sel.options[sel.selectedIndex].text);
    }
    return norm(td.innerText);
  }

  function readItems() {
    for (const t of document.querySelectorAll('table')) {
      if (t.closest('#' + ID) || t.offsetParent === null) continue;
      const firstTh = t.querySelector('th');
      if (!firstTh) continue;
      const headRow = firstTh.closest('tr');
      const headers = Array.from(headRow.children).map((c) => norm(c.innerText));
      const iNom = findCol(headers, CFG.cols.nominal);
      const iTuj = findCol(headers, CFG.cols.tujuan);
      const iUsr = findCol(headers, CFG.cols.user);
      const iFrom = findCol(headers, CFG.cols.from);
      const iSt = findCol(headers, CFG.cols.status);
      if (iNom < 0 || (iTuj < 0 && iUsr < 0)) continue;
      if (/penarikan|withdraw/i.test(headers[iNom])) headerMode = 'withdrawal';
      else if (/deposit/i.test(headers[iNom])) headerMode = 'deposit';

      let rows = Array.from(t.querySelectorAll('tbody tr'));
      if (!rows.length) {
        const w = t.closest('.dataTables_wrapper') || (t.parentElement && t.parentElement.parentElement);
        if (w) rows = Array.from(w.querySelectorAll('tbody tr'));
      }
      const items = [];
      rows.forEach((tr) => {
        const tds = Array.from(tr.children);
        if (tds.length <= 2 || !tds[iNom]) return; // baris "no data"
        const amount = parseFloat((tds[iNom].innerText || '').replace(/[^\d.]/g, '')) || 0;
        const user = iUsr >= 0 && tds[iUsr] ? norm(tds[iUsr].innerText) : '';
        const rawT = iTuj >= 0 && tds[iTuj] ? tds[iTuj].innerText : '';
        const from = iFrom >= 0 && tds[iFrom] ? cellText(tds[iFrom]) : '';
        const status = iSt >= 0 && tds[iSt] ? norm(tds[iSt].innerText) : '';
        const tj = parseTujuan(rawT);
        items.push(Object.assign(
          { user, amount, from, status, rawTujuan: norm(rawT), key: [user, amount, norm(rawT)].join('|') },
          tj
        ));
      });
      return items;
    }
    return null;
  }

  // Baris dilewati (tidak dibunyikan) jika Payment From / Payment To / Status memuat kata di daftar
  function skipReason(it) {
    const words = String(S.skipWords || '').split(',').map((x) => x.trim().toLowerCase()).filter(Boolean);
    if (!words.length) return '';
    const cols = { 'Payment From': it.from, 'Payment To': it.rawTujuan, 'Status': it.status };
    for (const name of Object.keys(cols)) {
      const v = String(cols[name] || '').toLowerCase();
      const w = words.find((x) => v.includes(x));
      if (w) return w + ' (' + name + ')';
    }
    return '';
  }

  function passFilter(it) {
    if (it.amount < Number(S.minNominal || 0)) return false;
    if (Number(S.maxNominal) > 0 && it.amount > Number(S.maxNominal)) return false;
    const kws = String(S.bankFilter || '').split(',').map((x) => x.trim().toLowerCase()).filter(Boolean);
    if (kws.length) {
      const hay = (it.bank + ' ' + it.holder).toLowerCase();
      if (!kws.some((k) => hay.includes(k))) return false;
    }
    return true;
  }

  // ---------- Interaksi halaman (hanya klik, tidak pernah reload) ----------
  function clickByText(label, tags) {
    for (const el of document.querySelectorAll(tags)) {
      if (el.closest('#' + ID)) continue;
      const own = Array.from(el.childNodes).filter((n) => n.nodeType === 3).map((n) => n.textContent).join('').trim();
      if (own === label || norm(el.textContent) === label) { el.click(); return true; }
    }
    return false;
  }
  const clickSearch = () => clickByText(CFG.searchButton, 'button, a');

  // ---------- Siklus: klik Cari -> baca tabel -> bunyikan ----------
  function scan() {
    const items = readItems();
    if (items === null) { setStatus('Tabel tidak ditemukan'); return; }

    const counter = {}, present = new Set(), eligible = [];
    let skipped = 0;
    items.forEach((it) => {
      counter[it.key] = (counter[it.key] || 0) + 1;
      it.id = it.key + '#' + counter[it.key];
      present.add(it.id);
      it.skip = skipReason(it);
      if (it.skip) { skipped++; return; }
      it.ok = passFilter(it);
      if (it.ok) eligible.push(it);
    });

    // catatan di Console (F12) setiap daftar berubah: berguna untuk melacak kenapa tidak bunyi
    const sig = curMode() + '|' + items.map((it) => it.id).join('~');
    if (sig !== lastSig) {
      lastSig = sig;
      try {
        console.log('[NOTIF PRO] mode=' + curMode() + ' | ' + location.pathname + ' | ' + items.length + ' data');
        console.table(items.map((it) => ({
          nama: it.user, nominal: it.amount, bank: it.bank, atasnama: it.holder,
          payment_from: it.from, status: it.status,
          dilewati: it.skip || '', dibunyikan: !it.skip && it.ok,
        })));
      } catch (e) {}
    }
    // transaksi yang sudah hilang dari daftar dilupakan
    Array.from(lastRead.keys()).forEach((id) => { if (!present.has(id)) lastRead.delete(id); });

    setStatus('Search done — ' + items.length + ' data' + (skipped ? ' · ' + skipped + ' dilewati' : ''));
    setMode();

    // tidak ada transaksi yang perlu dibunyikan -> diam
    const pool = S.repeat ? eligible : eligible.filter((it) => !lastRead.has(it.id));
    if (!pool.length) return;

    // yang belum pernah dibaca / paling lama dibaca didahulukan (bergiliran)
    pool.sort((a, b) => (lastRead.get(a.id) || 0) - (lastRead.get(b.id) || 0));
    const pick = pool.slice(0, Math.max(1, Number(S.maxItems) || 1));

    stopSpeech();
    pick.forEach((it) => {
      announceItem(it);
      lastRead.set(it.id, Date.now());
    });
  }

  async function loop() {
    if (!running) return;
    const t0 = Date.now();
    clickSearch();
    await sleep(CFG.waitAfterSearchMs);
    if (!running) return;
    scan();
    const gap = Math.max(5, Number(S.refreshSec) || 15) * 1000;
    scanTimer = setTimeout(loop, Math.max(1000, gap - (Date.now() - t0)));
  }

  function start() {
    running = true;
    lastRead.clear();
    unlockAudio();
    sayPlain('Sistem dimulai');
    setStatus('Running…');
    setStartBtn();
    scanTimer = setTimeout(loop, 800);
  }
  function stop() {
    running = false;
    clearTimeout(scanTimer);
    stopSpeech();
    setStatus('Stopped');
    setStartBtn();
  }

  // ---------- UI ----------
  const css = `
  #${ID}{position:fixed;top:16px;right:16px;width:400px;z-index:2147483647;
    background:#fff;color:#000;border:2px solid #000;border-radius:14px;
    box-shadow:0 12px 32px rgba(0,0,0,.35);
    font:14px/1.4 system-ui,'Segoe UI',Arial,sans-serif}
  #${ID} *{box-sizing:border-box}
  #${ID} .hd{display:flex;align-items:center;gap:8px;padding:12px 16px;
    background:#000;color:#fff;cursor:move;border-radius:11px 11px 0 0}
  #${ID} .hd b{flex:1;display:flex;align-items:baseline;gap:6px;font-size:16px;letter-spacing:.5px;font-weight:800}
  #${ID} .hd b i{font-style:normal;text-decoration:underline;text-underline-offset:3px}
  #${ID} .hd b small{color:#bbb;font-weight:400;font-size:11px}
  #${ID} .ib{border:1px solid #fff;border-radius:8px;background:#000;color:#fff;
    width:32px;height:32px;cursor:pointer;font-size:15px;line-height:1;
    display:flex;align-items:center;justify-content:center;padding:0;flex:none}
  #${ID} .ib:hover{background:#fff;color:#000}
  #${ID} .mode{border:1px solid #fff;border-radius:8px;background:#fff;color:#000;
    font-weight:800;font-size:11px;padding:0 10px;height:32px;cursor:pointer;
    display:flex;align-items:center;justify-content:center;text-align:center;white-space:nowrap;flex:none}
  #${ID} .tabs{display:flex;gap:0;margin:14px 16px 0;border:1px solid #000;border-radius:10px;overflow:hidden}
  #${ID} .tab{flex:1;text-align:center;padding:10px 4px;font-weight:800;font-size:12px;
    cursor:pointer;color:#000;background:#fff;border-right:1px solid #000;
    display:flex;align-items:center;justify-content:center}
  #${ID} .tab:last-child{border-right:0}
  #${ID} .tab.on{background:#000;color:#fff}
  #${ID} .pane{display:none;padding:14px 16px 4px}
  #${ID} .pane.on{display:block}
  #${ID} h4{margin:12px 0 8px;color:#000;font-size:11px;letter-spacing:.8px;
    font-weight:800;text-align:center;border-bottom:1px solid #000;padding-bottom:6px}
  #${ID} label{display:block;font-weight:700;font-size:12px;margin-bottom:6px;text-align:center}
  #${ID} input[type=number],#${ID} input[type=text],#${ID} select{
    width:100%;padding:10px 12px;border:1px solid #000;border-radius:8px;
    background:#fff;color:#000;font-size:14px;text-align:center}
  #${ID} select{text-align-last:center}
  #${ID} .row{display:flex;gap:12px}
  #${ID} .row>div{flex:1;min-width:0}
  #${ID} .chk{display:flex;align-items:center;justify-content:center;gap:8px;
    font-weight:700;font-size:12px;margin:10px 0;text-align:center}
  #${ID} .chk input{flex:none}
  #${ID} .hint{font-size:11px;color:#555;margin-top:6px;text-align:center;line-height:1.35}
  #${ID} .btn{display:block;width:calc(100% - 32px);margin:8px 16px 0;padding:13px;
    border-radius:10px;font-weight:800;font-size:14px;cursor:pointer;letter-spacing:.4px;
    text-align:center;border:1px solid #000}
  #${ID} .btn.test{background:#fff;color:#000}
  #${ID} .btn.test:hover{background:#000;color:#fff}
  #${ID} .btn.go{background:#000;color:#fff;margin-bottom:14px}
  #${ID} .btn.go.run{background:#fff;color:#000}
  #${ID} .ft{display:flex;align-items:center;justify-content:space-between;
    padding:10px 16px;border-top:2px solid #000;font-size:11px;font-weight:800}
  #${ID} .ft span{flex:1;text-align:center}
  #${ID} .ft span:first-child{text-align:left}
  #${ID} .ft span:last-child{text-align:right}
  #${ID}.min .tabs,#${ID}.min .pane,#${ID}.min .btn,#${ID}.min .ft{display:none}
  `;

  const html = `
  <div class="hd" id="${ID}-hd">
    <b>NOTIF <i>PRO</i> <small>v2</small></b>
    <button class="mode" id="${ID}-mode"></button>
    <button class="ib" id="${ID}-mute" title="Suara"></button>
    <button class="ib" id="${ID}-min" title="Kecilkan">&minus;</button>
    <button class="ib" id="${ID}-x" title="Tutup">&times;</button>
  </div>
  <div class="tabs">
    <div class="tab on" data-t="refresh">REFRESH</div>
    <div class="tab" data-t="nominal">NOMINAL</div>
    <div class="tab" data-t="payment">PAYMENT</div>
  </div>

  <div class="pane on" data-p="refresh">
    <h4>AUTO REFRESH</h4>
    <label>Interval (detik)</label>
    <input type="number" min="5" data-k="refreshSec">
    <div class="hint">Tiap interval script menekan tombol CARI (halaman tidak di-reload), lalu suara membacakan transaksi.</div>
    <h4>SUARA PER INTERVAL</h4>
    <div class="row">
      <div><label>Max Items</label><input type="number" min="1" data-k="maxItems"></div>
      <div></div>
    </div>
    <label class="chk"><input type="checkbox" data-k="repeat"> Ingatkan lagi selama masih pending</label>
    <div class="hint">Kalau tidak ada transaksi, tidak ada suara sama sekali.</div>
    <div style="height:10px"></div>
  </div>

  <div class="pane" data-p="nominal">
    <h4>FILTER NOMINAL (IDR)</h4>
    <div class="row">
      <div><label>Minimal</label><input type="number" min="0" data-k="minNominal"></div>
      <div><label>Maksimal (0 = bebas)</label><input type="number" min="0" data-k="maxNominal"></div>
    </div>
    <h4>NADA</h4>
    <label class="chk"><input type="checkbox" data-k="sfxOn"> Bunyikan nada sebelum suara</label>
    <div class="row">
      <div><label>Volume nada (0-1)</label><input type="number" min="0" max="1" step="0.1" data-k="sfxVolume"></div>
      <div></div>
    </div>
    <div class="hint">Deposit dan withdraw memakai nada yang sama (sound pertama).</div>
    <h4>SUARA</h4>
    <label>Mesin suara</label>
    <select data-k="engine">
      <option value="online">Online Google (suara Indonesia)</option>
      <option value="native">Bawaan browser (offline)</option>
    </select>
    <div class="hint">Online: teks yang dibacakan (nama, nominal, dll.) dikirim ke server Google Translate.</div>
    <div style="height:8px"></div>
    <label>Suara bawaan browser</label>
    <select data-k="voiceName" id="${ID}-voice"></select>
    <div class="hint" id="${ID}-voicehint"></div>
    <div style="height:8px"></div>
    <div class="row">
      <div><label>Kecepatan</label><input type="number" min="0.5" max="2" step="0.1" data-k="rate"></div>
      <div><label>Volume suara (0-1)</label><input type="number" min="0" max="1" step="0.1" data-k="volume"></div>
    </div>
    <div style="height:10px"></div>
  </div>

  <div class="pane" data-p="payment">
    <h4>KALIMAT SUARA DEPOSIT</h4>
    <input type="text" data-k="tplDeposit">
    <h4>KALIMAT SUARA WITHDRAW</h4>
    <input type="text" data-k="tplWithdraw">
    <div class="hint">Isian otomatis: {nama} {nominal} {bank} {atasnama} {rekening}</div>
    <h4>LEWATI (TIDAK DIBUNYIKAN)</h4>
    <input type="text" placeholder="contoh: qris, nxpay" data-k="skipWords">
    <div class="hint">Baris yang Payment From, Payment To, atau Status-nya memuat kata ini dilewati. Kosongkan untuk membaca semua.</div>
    <h4>FILTER BANK (opsional)</h4>
    <input type="text" placeholder="contoh: dana, bca" data-k="bankFilter">
    <div style="height:10px"></div>
  </div>

  <button class="btn test" id="${ID}-test">&#128266; TEST NOTIFIKASI</button>
  <button class="btn go" id="${ID}-go"></button>
  <div class="ft"><span id="${ID}-st">Siap</span><span id="${ID}-clock"></span></div>
  `;

  function setStatus(t) { const e = document.getElementById(ID + '-st'); if (e) e.textContent = t; }
  function setStartBtn() {
    const b = document.getElementById(ID + '-go');
    if (!b) return;
    b.textContent = running ? '■ STOP SYSTEM' : '▶ START SYSTEM';
    b.classList.toggle('run', running);
  }
  function setMode() {
    const m = document.getElementById(ID + '-mode');
    const u = document.getElementById(ID + '-mute');
    if (m) {
      const cur = curMode().toUpperCase();
      m.textContent = S.modeSel === 'auto' ? 'AUTO · ' + cur : cur;
      m.title = 'Klik untuk ganti: AUTO (ikut alamat halaman) / DEPOSIT / WITHDRAWAL';
    }
    if (u) u.textContent = S.muted ? '🔇' : '🔊';
  }

  // isi daftar suara bawaan browser
  function fillVoices() {
    const sel = document.getElementById(ID + '-voice');
    const hint = document.getElementById(ID + '-voicehint');
    if (!sel || !('speechSynthesis' in window)) return;
    const voices = speechSynthesis.getVoices();
    sel.innerHTML = '';
    const auto = document.createElement('option');
    auto.value = '';
    auto.textContent = 'Otomatis (Indonesia jika ada)';
    sel.appendChild(auto);
    voices.forEach((v) => {
      const o = document.createElement('option');
      o.value = v.name;
      o.textContent = v.name + ' (' + v.lang + ')';
      sel.appendChild(o);
    });
    sel.value = S.voiceName || '';
    const hasId = voices.some((v) => /^id/i.test(v.lang));
    if (hint) {
      hint.textContent = hasId
        ? 'Suara Indonesia terdeteksi di browser ini.'
        : 'Tidak ada suara Indonesia di browser ini — pilih "Online Google" di atas.';
    }
  }

  function build() {
    if (document.getElementById(ID)) return;
    if (!document.getElementById(ID + '-css')) {
      const st = document.createElement('style');
      st.id = ID + '-css';
      st.textContent = css;
      document.head.appendChild(st);
    }

    const box = document.createElement('div');
    box.id = ID;
    box.innerHTML = html;
    document.body.appendChild(box);

    fillVoices();
    if ('speechSynthesis' in window) on(speechSynthesis, 'voiceschanged', fillVoices);

    // nilai awal + simpan perubahan
    box.querySelectorAll('[data-k]').forEach((el) => {
      const k = el.dataset.k;
      if (el.type === 'checkbox') el.checked = !!S[k];
      else if (k !== 'voiceName') el.value = S[k];
      on(el, 'change', () => {
        S[k] = el.type === 'checkbox' ? el.checked : (el.type === 'number' ? Number(el.value) : el.value);
        save();
      });
    });

    // tab
    box.querySelectorAll('.tab').forEach((tab) => {
      on(tab, 'click', () => {
        box.querySelectorAll('.tab').forEach((x) => x.classList.toggle('on', x === tab));
        box.querySelectorAll('.pane').forEach((p) => p.classList.toggle('on', p.dataset.p === tab.dataset.t));
      });
    });

    // tombol header
    on(document.getElementById(ID + '-mode'), 'click', () => {
      const order = ['auto', 'deposit', 'withdrawal'];
      S.modeSel = order[(order.indexOf(S.modeSel) + 1) % order.length] || 'auto';
      save(); setMode(); lastRead.clear();
    });
    on(document.getElementById(ID + '-mute'), 'click', () => {
      S.muted = !S.muted;
      if (S.muted) stopSpeech();
      save(); setMode();
    });
    on(document.getElementById(ID + '-min'), 'click', () => box.classList.toggle('min'));
    on(document.getElementById(ID + '-x'), 'click', hide);

    // tes & start
    on(document.getElementById(ID + '-test'), 'click', () => {
      unlockAudio();
      stopSpeech();
      const saved = S.muted; S.muted = false;
      announceItem({ user: 'Budi88', amount: 2500000, bank: 'BCA', holder: 'Siti Aminah', number: '081234567890' });
      S.muted = saved;
    });
    on(document.getElementById(ID + '-go'), 'click', () => (running ? stop() : start()));

    // geser panel
    const hd = document.getElementById(ID + '-hd');
    on(hd, 'mousedown', (e) => {
      if (e.target.closest('button')) return;
      const r = box.getBoundingClientRect();
      const dx = e.clientX - r.left, dy = e.clientY - r.top;
      const move = (ev) => {
        box.style.left = Math.max(0, ev.clientX - dx) + 'px';
        box.style.top = Math.max(0, ev.clientY - dy) + 'px';
        box.style.right = 'auto';
      };
      const up = () => { document.removeEventListener('mousemove', move); document.removeEventListener('mouseup', up); };
      document.addEventListener('mousemove', move);
      document.addEventListener('mouseup', up);
    });

    // jam
    const tick = () => {
      const c = document.getElementById(ID + '-clock');
      if (c) c.textContent = new Date().toLocaleTimeString('id-ID', { hour12: false });
    };
    tick(); clearInterval(clockTimer); clockTimer = setInterval(tick, 1000);

    setMode(); setStartBtn();
  }

  // ---------- Versi console: langsung tampil di tab ini ----------
  function show() { build(); }
  function hide() {
    stop();
    clearInterval(clockTimer);
    const box = document.getElementById(ID);
    if (box) box.remove();
  }
  window.__notifpro = { show, hide };
  show();
})();
